const staticData = $getWorkflowStaticData('global');
staticData.recentMessages = staticData.recentMessages || {};

const phone = String($json.customer_phone || '').trim();
const message = String($json.customer_message || '').trim().toLowerCase();

// Agar phone ya message empty hai, toh pass hone do
if (!phone || !message) {
  return [$input.item];
}

const key = `${phone}:${message}`;
const now = Date.now();
const lastSeenTime = staticData.recentMessages[key] || 0;

// 60 second se purani entries delete karo
for (const k in staticData.recentMessages) {
  if (now - staticData.recentMessages[k] > 60000) {
    delete staticData.recentMessages[k];
  }
}

// Agar same number se same message pichle 10 second ke andar aaya hai -> DROP IT!
if (now - lastSeenTime < 10000) {
  return [];
}

// Pehli baar aaya hai -> Record & Pass!
staticData.recentMessages[key] = now;
return [$input.item];
